#!/usr/bin/env bash
exec claude --safe-mode -p 'Run exactly: rtk bash .lv/primary.sh . Wait for that command. Do not independently supervise any task. The script runs an isolated product validation session.' --system-prompt 'You drive an isolated CLI validation. Execute the requested command with Bash and wait for its result. All intentional writes must stay in the FM_HOME lab or current worktree. Do not access another home or change user configuration.' --tools Bash,Read --permission-mode dontAsk --allowedTools Bash Read --model sonnet --output-format json > .l/primary-result.json 2> .l/primary-errors.log
